using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class BreathStreamingTests {
 static int count;static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);Console.WriteLine("PASS "+name);count++;}
 public static void Main(){string root=Path.Combine(Path.GetTempPath(),"V15_stream_breath_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"breaths"));new Wave{Rate=24000,Samples=Enumerable.Range(0,4800).Select(i=>(short)(3000*Math.Sin(i*.13))).ToArray()}.Write(Path.Combine(root,"breaths","fixture.wav"));var engine=new FakeSpeech{Root=root,Seconds=1};
  var cues=Enumerable.Range(0,4).Select(i=>new Cue{Id=i+1,Start=i*4,End=i*4+3,Text="This sentence ends here."}).ToList();string srt=Scripts.ToSrt(cues);string path=Renderer.Render(cues,engine,new RenderOptions{SlowShort=false},Path.Combine(root,"auto.wav"),(n,m)=>{});var w=Wave.Read(path);
  Check(cues.Count(c=>c.Status.Contains("hơi thở"))==1&&cues[2].Status.Contains("hơi thở"),"Streaming Auto breath is sparse and occurs after the third sentence");Check(Math.Abs(w.Duration-15)<1.0/24000&&Scripts.ToSrt(cues)==srt,"Streaming breath keeps all locked source times and final duration");Check(w.Samples.Skip((int)(9.06*24000)).Take(1000).Any(x=>x!=0),"Synthetic breath fixture is written into the allowed silent space");Check(w.Samples.Skip(11*24000).Take(24000).All(x=>x==0),"Locked inter-cue gap remains silent after breath insertion");
  cues=Enumerable.Range(0,4).Select(i=>new Cue{Id=i+1,Start=i*4,End=i*4+3,Text="Hello there."}).ToList();path=Renderer.Render(cues,engine,new RenderOptions{Locked=false,Breathing=BreathMode.Custom,BreathEvery=1},Path.Combine(root,"custom.wav"),(n,m)=>{});Check(cues.Take(3).All(c=>c.Status.Contains("hơi thở"))&&!cues.Last().Status.Contains("hơi thở"),"Custom breath frequency and no trailing breath survive streaming");Check(cues[1].Start-cues[0].End>.25&&Math.Abs(Wave.Read(path).Duration-cues.Last().End)<.001,"Flexible timeline reserves the complete breath without clipping");
  path=Renderer.Render(cues,engine,new RenderOptions{Locked=false,Breathing=BreathMode.None},Path.Combine(root,"none.wav"),(n,m)=>{});Check(cues.All(c=>!c.Status.Contains("hơi thở")),"Off mode inserts no breath");Check(Directory.GetFiles(root,"*.wav").Length==3&&!Directory.GetFiles(root,"*.tmp").Any(),"Only final WAVs are published with synthetic breath fixtures");Console.WriteLine("TOTAL BREATH STREAMING "+count+" passed.");
 }
}
